// @control {"name":"darkness","label":"Darkness","type":"float","default":1,"min":0,"max":1}
/// @brief Darkens the layer below.
// Contact: shaders@example.org; version 1 needs no @requires line.
vec4 material(vec2 uv) {
  vec3 c = texture(r_input, uv).rgb; // @darkness scales this
  /* @note a block comment that does not start a line */
  return vec4(c * p_darkness, 1.0);
}

